PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/refinement/1.0/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?zone ?zoneName ?tsid WHERE {
  ?sensor a brick:ElectricPowerSensor ;
          brick:hasPropertyType brick:ElectricPower .
  ?sensor ref:hasExternalReference ?ext .
  ?ext ref:hasTimeseriesId ?tsid .
  ?loc brick:hasSubComponent ?sensor .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor ?zone ?zoneName WHERE {
  ?sensor a brick:ElectricPowerSensor .
  ?sensor brick:isPointOf ?zone .
  ?zone a brick:Zone .
  OPTIONAL { ?zone rdfs:label ?zoneName }
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor (STR(?type) AS ?typ) ?zone WHERE {
  ?sensor brick:isPointOf ?zone .
  ?sensor a ?type .
  ?zone a brick:Zone .
}

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?sensor (STR(?type) AS ?typ) ?zone WHERE {
  ?zone a brick:Zone .
  ?zone brick:feedsAndServedBy ?port .
} LIMIT 10

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?point (STR(?type) AS ?typ) ?target WHERE {
  ?point brick:isPointOf ?target .
  ?point a ?type .
  ?target a brick:Zone .
} LIMIT 200

PREFIX brick: <https://brickschema.org/schema/Brick#>
SELECT ?zone (STR(?type) AS ?typ) WHERE {
  ?zone brick:isPointOf|?p ?x .
} LIMIT 5

